  // 1. 定义设定标签和分割锚点
  const settingsRegex = /<additional_settings>([\s\S]*?)<\/additional_settings>/g;
  const pivotTag = '<@D_Split>';

  // 2. 获取分割点位置
  const pivotIndex = content.indexOf(pivotTag);

  const beforeMatches = [];
  const afterMatches = [];

  // 3. 核心逻辑：使用 replace 的回调函数一次性完成“提取”和“保护”
  // match: 完整的 <标签>内容</标签>
  // innerText: 标签里面的内容
  // offset: 标签在全文中的索引位置
  let result = content.replace(settingsRegex, (match, innerText, offset) => {
    let contentToExtract = innerText;
    let contentToKeep = "";

    // === 保护名单 ===
    // 如果发现这些词，把它们从提取内容中剔除，并添加到 contentToKeep 用于保留在原文
    const protectedKeywords = [
      "\n\n[Start writing]",
      "\n\n{{user}}: ",
      "\n\n{{char}}: "
    ];

    protectedKeywords.forEach(keyword => {
      if (contentToExtract.includes(keyword)) {
        // 1. 从提取物中删掉关键词
        contentToExtract = contentToExtract.replace(keyword, "");
        // 2. 将关键词加入保留名单 (用来替换掉原来的标签)
        contentToKeep += keyword;
      }
    });

    // === 分组逻辑 ===
    // 只有当提取内容不为空时才进行保存
    if (contentToExtract.trim()) {
      if (pivotIndex !== -1 && offset > pivotIndex) {
        afterMatches.push(contentToExtract);
      } else {
        beforeMatches.push(contentToExtract);
      }
    }

    // === 返回值 ===
    return contentToKeep;
  });

  // 4. 清理分割锚点 <@D_Split>
  result = result.replace(pivotTag, '');

  // 5. 组合提取出的内容
  const beforeContent = beforeMatches.join('\n').trim();
  const afterContent = afterMatches.join('\n').trim();

  // 6. 注入到占位符
  result = result
    .replaceAll(
      '<|@D_before|>',
      beforeContent ? '\n' + beforeContent : ''
    )
    .replaceAll(
      '<|@D_after|>',
      afterContent ? '\n' + afterContent : ''
    );

  return result.trim();
};

